INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205AHRG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'grid_in', E'A bag contains 7 red marbles, 11 blue marbles, and 5 green marbles. If one marble is selected at random, what is the probability that it is blue? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/23', ARRAY['11/23', '0.478', '.478'], E'The total number of marbles is 7 + 11 + 5 = 23. The number of blue marbles is 11. The probability of selecting a blue marble is 11/23.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20DJMTV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A machine fills 91 bottles in 7 minutes. At this constant rate, how many bottles does the machine fill in 23 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '299', ARRAY['299'], E'The machine fills 91 / 7 = 13 bottles per minute. In 23 minutes it fills 13 × 23 = 299 bottles.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22ELV2T', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $13x + 7y = 91$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$13$"},{"key":"C","text":"$91$"},{"key":"D","text":"$\\frac{91}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting: $13(0) + 7y = 91$, so $7y = 91$ and $y = 13$. The value 7 confuses the coefficient of $y$ with the intercept value. The value 91 ignores the coefficient of $y$ and treats the constant as the intercept directly. The value $\\frac{91}{13}$ finds the $x$-intercept (setting $y = 0$) instead of the $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22L0HF2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter charges 47 dollars for each hour of labor plus a flat fee of 89 dollars for materials. If a customer has a budget of no more than 650 dollars, which inequality represents the number of hours \\(h\\) of labor the customer can afford?', NULL, $lyceon_json$[{"key":"A","text":"\\(47h + 89 \\leq 650\\)"},{"key":"B","text":"\\(47h + 89 \\geq 650\\)"},{"key":"C","text":"\\(89h + 47 \\leq 650\\)"},{"key":"D","text":"\\(47h - 89 \\leq 650\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the hourly rate times the number of hours plus the flat fee: \\(47h + 89\\). Since the customer can spend no more than 650 dollars, the total must be less than or equal to 650, giving \\(47h + 89 \\leq 650\\). Using \\(\\geq\\) reverses the budget constraint, requiring spending at least 650 dollars rather than at most. Swapping the coefficients so that 89 multiplies \\(h\\) and 47 is the constant misidentifies which value is the hourly rate and which is the flat fee. Subtracting 89 instead of adding it misrepresents the flat fee as a discount rather than an additional cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23IEDWY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $f(x) = -3(x + 4)(x - 9)$ achieves its maximum value at $x = k$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/2', ARRAY['5/2', '2.5'], E'Since $f(x) = -3(x + 4)(x - 9)$ has a negative leading coefficient, the parabola opens downward and has a maximum at its vertex. The zeros of the function are $x = -4$ and $x = 9$. By the symmetry of a parabola, the vertex lies at the midpoint of the zeros: $k = \\frac{-4 + 9}{2} = \\frac{5}{2}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23OVOH4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of \\(x\\) in the solution to the system of equations below?\\n\\n\\(3x + y = 29\\)\\n\\(x - y = 7\\)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Adding the two equations eliminates \\(y\\): \\(3x + y + x - y = 29 + 7\\), which simplifies to \\(4x = 36\\), so \\(x = 9\\). Substituting back, \\(y = 29 - 3(9) = 2\\), confirming the solution \\((9, 2)\\) satisfies both equations.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM245JWTC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $PQR$, angle $Q = 90°$, $PQ = 14$, and $\\tan(P) = \\frac{5}{7}$. What is the area of triangle $PQR$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '70', ARRAY['70'], E'In right triangle $PQR$ with the right angle at $Q$, the side opposite angle $P$ is $QR$ and the side adjacent to angle $P$ is $PQ$. Since $\\tan(P) = \\frac{QR}{PQ} = \\frac{5}{7}$ and $PQ = 14$, we get $QR = \\frac{5}{7} \\times 14 = 10$. The area of the triangle is $\\frac{1}{2} \\times PQ \\times QR = \\frac{1}{2} \\times 14 \\times 10 = 70$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24HIWGS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is composed of a rectangular prism topped by a half-cylinder. The rectangular prism has a length of $10$ cm, a width of $6$ cm, and a height of $8$ cm. The half-cylinder has a diameter equal to the width of the prism ($6$ cm) and a length of $10$ cm. Which of the following is closest to the total volume, in cubic centimeters, of the solid?', NULL, $lyceon_json$[{"key":"A","text":"$480$"},{"key":"B","text":"$621$"},{"key":"C","text":"$763$"},{"key":"D","text":"$1046$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rectangular prism has volume $10 \\times 6 \\times 8 = 480$ cubic cm. The half-cylinder has radius $3$ cm (half of the $6$ cm diameter) and length $10$ cm, so its volume is $\\frac{1}{2} \\pi r^2 \\times \\text{length} = \\frac{1}{2} \\pi (9)(10) = 45\\pi \\approx 141.4$ cubic cm. The total volume is approximately $480 + 141.4 \\approx 621$ cubic cm. The value $480$ accounts for only the prism and ignores the half-cylinder entirely. The value $763$ uses a full cylinder instead of a half-cylinder, adding $90\\pi \\approx 283$ to $480$. The value $1046$ uses the diameter ($6$) as the radius in the half-cylinder formula, computing $\\frac{1}{2}\\pi(36)(10) = 180\\pi \\approx 565$ and adding it to $480$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24PU5KS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A store sells a jacket for 83 dollars. If the sales tax rate is 7%, what is the total cost, in dollars, of the jacket including tax?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '88.81', ARRAY['88.81'], E'The tax is 0.07 × 83 = 5.81 dollars. The total cost is 83 + 5.81 = 88.81 dollars.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24RSBEK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $3(2x - 7) + 11 = 5x + 13$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-23$"},{"key":"D","text":"$\\frac{23}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing on the left side: $6x - 21 + 11 = 5x + 13$, which simplifies to $6x - 10 = 5x + 13$. Subtracting $5x$ from both sides gives $x - 10 = 13$. Adding 10 to both sides yields $x = 23$. The value 9 results from failing to distribute correctly before combining like terms. The value $-23$ comes from a sign error when moving terms across the equation. The fraction $\\frac{23}{7}$ results from incorrectly dividing by the original coefficient of $x$ instead of simplifying first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2611AY7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(2) = 19$ and $f(9) = 47$. For what value of $x$ does $f(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{11}{4}$"},{"key":"B","text":"$\\frac{11}{4}$"},{"key":"C","text":"$-\\frac{4}{11}$"},{"key":"D","text":"$-\\frac{19}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{47 - 19}{9 - 2} = \\frac{28}{7} = 4$. Using the point $(2, 19)$: $f(x) = 4(x - 2) + 19 = 4x + 11$. Setting $f(x) = 0$: $4x + 11 = 0$, so $x = -\\frac{11}{4}$. The value $\\frac{11}{4}$ results from dropping the negative sign when solving. The value $-\\frac{4}{11}$ comes from inverting the fraction when isolating $x$. The value $-\\frac{19}{4}$ results from using the $y$-value of a given point instead of the correct $y$-intercept when setting the function equal to zero.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26BIQM2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $9$ inches. What is the length, in inches, of an arc that subtends a central angle of $140°$?', NULL, $lyceon_json$[{"key":"A","text":"$7\\pi$"},{"key":"B","text":"$\\frac{7\\pi}{2}$"},{"key":"C","text":"$\\frac{63\\pi}{2}$"},{"key":"D","text":"$14\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'Arc length equals $\\frac{\\theta}{360°} \\times 2\\pi r$. Substituting gives $\\frac{140}{360} \\times 2\\pi(9) = \\frac{7}{18} \\times 18\\pi = 7\\pi$. The value $\\frac{7\\pi}{2}$ results from using $\\pi r$ instead of $2\\pi r$ for the circumference, effectively halving the correct answer. The value $\\frac{63\\pi}{2}$ comes from using the area formula $\\pi r^2 = 81\\pi$ instead of the circumference, computing $\\frac{140}{360} \\times 81\\pi$. The value $14\\pi$ doubles the correct answer, as if using $280°$ or miscounting the fraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2767MU7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $f(t) = 230 - 17t$ models the number of gallons of water remaining in a tank $t$ hours after a drain is opened. Which of the following best describes what the value $-17$ represents in this context?', NULL, $lyceon_json$[{"key":"A","text":"The tank loses 17 gallons per hour."},{"key":"B","text":"The tank started with 17 gallons."},{"key":"C","text":"It takes 17 hours to empty the tank."},{"key":"D","text":"The tank gains 17 gallons per hour."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $f(t) = 230 - 17t$, the coefficient of $t$ is $-17$, which represents the rate of change. Since it is negative, the water level decreases by 17 gallons each hour. The claim that the tank started with 17 gallons confuses the rate of change with the initial value, which is 230. The claim about 17 hours confuses the rate with the time variable. The claim that the tank gains 17 gallons per hour ignores the negative sign, reversing the direction of change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2818N9I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A population of 4,300 organisms decreases by 18% in the first year and then increases by 11% in the second year. What is the population at the end of the second year, rounded to the nearest whole number?', NULL, $lyceon_json$[{"key":"A","text":"$3,914$"},{"key":"B","text":"$3,526$"},{"key":"C","text":"$3,999$"},{"key":"D","text":"$3,698$"}]$lyceon_json$::jsonb, 'A', NULL, E'After the first year: 4300 × 0.82 = 3526. After the second year: 3526 × 1.11 = 3913.86, which rounds to 3914. The value 3526 results from applying only the first-year decrease and stopping there. The value 3999 comes from treating the net change as a single 7% decrease (18% minus 11%), giving 4300 × 0.93 = 3999, which incorrectly adds percentage changes instead of compounding them. The value 3698 results from an arithmetic error when multiplying 3526 × 1.11.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM282WLSN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2.3x + 11$. According to this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$31.7$"},{"key":"B","text":"$29.3$"},{"key":"C","text":"$20.7$"},{"key":"D","text":"$33.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting x = 9 into the equation: y = 2.3(9) + 11 = 20.7 + 11 = 31.7. The value 29.3 results from computing 2.3 × 9 as 18.3 instead of 20.7. The value 20.7 comes from computing 2.3 × 9 correctly but omitting the addition of 11. The value 33.7 results from computing 2.3 × 9 as 22.7 and then adding 11.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283RG1M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 residents from a city with 52,000 residents found that 37% preferred expanding the public library. Based on this sample, which of the following is the best estimate of the number of residents in the city who prefer expanding the public library?', NULL, $lyceon_json$[{"key":"A","text":"148"},{"key":"B","text":"14,800"},{"key":"C","text":"19,240"},{"key":"D","text":"52,000"}]$lyceon_json$::jsonb, 'C', NULL, E'The best estimate is 37% of the total city population: 0.37 times 52,000 = 19,240. The distractor 148 applies the percentage to the sample size (0.37 times 400) rather than the population. The distractor 14,800 results from an arithmetic error such as computing 0.37 times 40,000 instead of 52,000. The distractor 52,000 is simply the total population, ignoring the percentage entirely.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM284L9ZE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $25x^2 - 49y^2$?', NULL, $lyceon_json$[{"key":"A","text":"$(5x - 7y)^2$"},{"key":"B","text":"$(5x + 7y)(5x - 7y)$"},{"key":"C","text":"$(25x + 49y)(x - y)$"},{"key":"D","text":"$(5x - 49y)(5x + y)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The expression $25x^2 - 49y^2$ is a difference of squares: $(5x)^2 - (7y)^2$. Applying the difference of squares identity $a^2 - b^2 = (a+b)(a-b)$ yields $(5x + 7y)(5x - 7y)$. The distractor $(5x - 7y)^2$ expands to $25x^2 - 70xy + 49y^2$, which includes a middle term. The distractor $(25x + 49y)(x - y)$ incorrectly factors without taking square roots of the coefficients. The distractor $(5x - 49y)(5x + y)$ incorrectly pairs the terms and does not produce the original expression when expanded.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28W5DDZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A data set consists of the values 14, 19, 23, 23, 27, 31, and 38. What is the median of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'There are 7 values listed in ascending order. The median is the 4th value (the middle value), which is 23.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A7FLDP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A small business produces two types of candles. Each type-A candle requires 3 ounces of wax and 2 minutes of labor. Each type-B candle requires 5 ounces of wax and 1 minute of labor. The business has at most 310 ounces of wax and at most 94 minutes of labor available. If \\(a\\) and \\(b\\) represent the number of type-A and type-B candles produced, respectively, which system of inequalities models these constraints?', NULL, $lyceon_json$[{"key":"A","text":"\\(3a + 5b \\leq 310\\) and \\(2a + b \\leq 94\\)"},{"key":"B","text":"\\(5a + 3b \\leq 310\\) and \\(a + 2b \\leq 94\\)"},{"key":"C","text":"\\(3a + 5b \\leq 310\\) and \\(a + 2b \\leq 94\\)"},{"key":"D","text":"\\(3a + 5b \\geq 310\\) and \\(2a + b \\geq 94\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Type-A uses 3 oz wax and type-B uses 5 oz wax, so the wax constraint is \\(3a + 5b \\leq 310\\). Type-A uses 2 min labor and type-B uses 1 min labor, so the labor constraint is \\(2a + b \\leq 94\\). Swapping the wax coefficients so that 5 multiplies \\(a\\) and 3 multiplies \\(b\\) assigns each candle type the other''s wax requirement. Mixing up the labor coefficients by assigning 2 minutes to type-B and 1 minute to type-A reverses which candle is more labor-intensive. Using \\(\\geq\\) instead of \\(\\leq\\) misinterprets ''at most'' as ''at least,'' which would require using a minimum rather than staying within the available supply.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AWJIIY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $JKL$, the measure of angle $J$ is $(5x - 2)°$, the measure of angle $K$ is $(3x + 7)°$, and the measure of angle $L$ is $(2x + 15)°$. What is the measure, in degrees, of the largest angle in triangle $JKL$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '78', ARRAY['78'], E'The sum of the interior angles of a triangle is $180°$, so $(5x - 2) + (3x + 7) + (2x + 15) = 180$. Combining like terms gives $10x + 20 = 180$, so $10x = 160$ and $x = 16$. Substituting back: angle $J = 5(16) - 2 = 78°$, angle $K = 3(16) + 7 = 55°$, and angle $L = 2(16) + 15 = 47°$. The largest angle is $78°$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BBQGF5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A teacher records quiz scores for 11 students: 41, 47, 52, 55, 58, 61, 63, 67, 71, 79, 93. The teacher decides to replace the highest score (93) with 71. Which of the following correctly describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases and the median stays the same."},{"key":"C","text":"Both the mean and the median stay the same."},{"key":"D","text":"The mean stays the same and the median decreases."}]$lyceon_json$::jsonb, 'B', NULL, E'The original sum is 41 + 47 + 52 + 55 + 58 + 61 + 63 + 67 + 71 + 79 + 93 = 687, with mean 687/11 ≈ 62.5. Replacing 93 with 71 reduces the sum by 22 to 665, so the new mean is 665/11 ≈ 60.5 — the mean decreases. The median is the 6th value in the sorted list. Originally: 41, 47, 52, 55, 58, 61, 63, 67, 71, 79, 93 — the median is 61. After replacement the sorted list is 41, 47, 52, 55, 58, 61, 63, 67, 71, 71, 79 — the 6th value is still 61, so the median stays the same. Claiming both decrease incorrectly assumes that lowering a value above the median shifts the median. Claiming both stay the same ignores that lowering a data value reduces the sum and therefore the mean. Claiming the mean stays the same while the median decreases reverses which measure is affected.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CX02TE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$ units. What is the area, in square units, of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$26\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $\\pi r^2$. With $r = 13$, the area is $\\pi(13)^2 = 169\\pi$. The value $13\\pi$ comes from using $\\pi r$ instead of $\\pi r^2$, omitting the squaring. The value $26\\pi$ equals $2\\pi r$, which is the circumference formula, not the area. The value $676\\pi$ results from squaring the diameter ($26^2 = 676$) instead of the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DGKZ2Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A class has 31 students. Of these, 13 play basketball, 9 play soccer, and 4 play both basketball and soccer. If a student is chosen at random, what is the probability that the student plays basketball or soccer?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{18}{31}$"},{"key":"B","text":"$\\frac{22}{31}$"},{"key":"C","text":"$\\frac{26}{31}$"},{"key":"D","text":"$\\frac{13}{31}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, the number who play basketball or soccer is 13 + 9 - 4 = 18. The probability is 18/31. The distractor 22/31 results from adding 13 + 9 without subtracting the overlap. The distractor 26/31 results from adding 13 + 9 + 4, incorrectly adding the overlap instead of subtracting it. The distractor 13/31 considers only basketball players, ignoring soccer entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DOQYKT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'An item''s price was first increased by 30%, then decreased by $p$ percent, resulting in a final price that is 4.5% less than the original price. What is the value of $p$, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$26.5$"},{"key":"B","text":"$34.5$"},{"key":"C","text":"$25.5$"},{"key":"D","text":"$30.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the original price be 1. After a 30% increase the price is 1.30. After a p% decrease the price is 1.30(1 - p/100). This equals 0.955 (which is 4.5% less than original). So 1 - p/100 = 0.955/1.30 = 0.73461..., giving p/100 = 0.26538... and p is approximately 26.5. The value 34.5 results from setting up the equation as 1.30 - p/100 = 0.955 (subtracting p/100 from 1.30 instead of multiplying by the factor). The value 25.5 comes from a rounding error when dividing 0.955 by 1.30. The value 30.0 comes from incorrectly assuming the decrease percentage equals the increase percentage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EG5M5R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for 5 cups of broth for every 3 cups of rice. If a chef uses 11 cups of rice, how many cups of broth does the chef need?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{33}{5}$"},{"key":"B","text":"$\\frac{55}{3}$"},{"key":"C","text":"$\\frac{53}{5}$"},{"key":"D","text":"$\\frac{15}{11}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of broth to rice is 5 to 3, so broth = (5/3) × rice. With 11 cups of rice: (5/3)(11) = 55/3 cups of broth. The value 33/5 results from inverting the ratio and using 3/5 instead of 5/3. The value 53/5 comes from a multiplication error when computing 5 × 11. The value 15/11 comes from setting the proportion incorrectly as 3/5 = rice/broth and further inverting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G0KEI1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = ax^2 + bx + c$ has its vertex at $(3, -11)$ and passes through the point $(5, 1)$. What is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$1$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using vertex form: $f(x) = a(x - 3)^2 - 11$. Substituting the point $(5, 1)$: $1 = a(5 - 3)^2 - 11 = 4a - 11$, so $4a = 12$ and $a = 3$. Expanding: $f(x) = 3(x - 3)^2 - 11 = 3x^2 - 18x + 27 - 11 = 3x^2 - 18x + 16$. Therefore $a + b + c = 3 + (-18) + 16 = 1$. Equivalently, $a + b + c = f(1) = 3(1) - 18(1) + 16 = 1$. The distractor $-8$ comes from computing $-a + b + c$ (evaluating at $x = -1$ instead of $x = 1$). The distractor $-5$ arises from a sign error when expanding the vertex form. The distractor $16$ comes from only computing the constant term $c$ without including $a$ and $b$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G7M3M9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq \\frac{2}{5}$, which of the following is equivalent to $\\frac{10x^2 + 29x - 14}{5x - 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 7$"},{"key":"B","text":"$2x - 7$"},{"key":"C","text":"$2x + \\frac{29}{5}$"},{"key":"D","text":"$10x + 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator by finding two numbers that multiply to $10 \\cdot (-14) = -140$ and add to $29$. Those numbers are $35$ and $-4$: $10x^2 + 35x - 4x - 14 = 5x(2x + 7) - 2(2x + 7) = (5x - 2)(2x + 7)$. Dividing by $(5x - 2)$ leaves $2x + 7$. The distractor $2x - 7$ results from a sign error in factoring. The distractor $2x + \\frac{29}{5}$ results from dividing only the linear coefficient by $5$ without completing the polynomial division. The distractor $10x + 7$ results from failing to divide the leading coefficient during factoring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GTUCCK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $11x^5 \\cdot 2x^3$?', NULL, $lyceon_json$[{"key":"A","text":"$22x^{15}$"},{"key":"B","text":"$13x^8$"},{"key":"C","text":"$22x^8$"},{"key":"D","text":"$22x^{53}$"}]$lyceon_json$::jsonb, 'C', NULL, E'To multiply monomials, multiply the coefficients and add the exponents: $11 \\times 2 = 22$ and $x^5 \\cdot x^3 = x^{5+3} = x^8$, giving $22x^8$. The value $22x^{15}$ results from multiplying the exponents instead of adding them. The value $13x^8$ adds the coefficients instead of multiplying them. The value $22x^{53}$ concatenates the exponents as digits rather than adding them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GZGFF6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $ABC$ with the right angle at $C$, leg $AC = 9$ and leg $BC = 14$. What is the value of $\\tan(A)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{14}$"},{"key":"B","text":"$\\frac{14}{9}$"},{"key":"C","text":"$\\frac{9}{23}$"},{"key":"D","text":"$\\frac{14}{23}$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a right triangle, $\\tan(A) = \\frac{\\text{opposite}}{\\text{adjacent}}$. The side opposite angle $A$ is $BC = 14$ and the side adjacent to angle $A$ is $AC = 9$, so $\\tan(A) = \\frac{14}{9}$. The value $\\frac{9}{14}$ reverses the opposite and adjacent sides. The values $\\frac{9}{23}$ and $\\frac{14}{23}$ incorrectly use $9 + 14 = 23$ as though it were the hypotenuse, confusing addition of legs with the Pythagorean theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HSIDLL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant \\(k\\) does the system of equations below have no solution?\\n\\n\\(6x - 9y = 14\\)\\n\\(4x - ky = 5\\)', NULL, $lyceon_json$[{"key":"A","text":"\\(-6\\)"},{"key":"B","text":"\\(-4\\)"},{"key":"C","text":"\\(4\\)"},{"key":"D","text":"\\(6\\)"}]$lyceon_json$::jsonb, 'D', NULL, E'For the system to have no solution, the two equations must represent parallel lines — same slope but different intercepts. Rewriting the first equation: \\(y = \\frac{6}{9}x - \\frac{14}{9} = \\frac{2}{3}x - \\frac{14}{9}\\). Rewriting the second: \\(y = \\frac{4}{k}x - \\frac{5}{k}\\). Setting the slopes equal gives \\(\\frac{4}{k} = \\frac{2}{3}\\), so \\(k = 6\\). Checking the intercepts: \\(-\\frac{14}{9} \\neq -\\frac{5}{6}\\), confirming the lines are parallel with distinct intercepts. The value \\(-6\\) results from introducing an incorrect negative sign when setting up the proportionality. The value \\(-4\\) comes from incomplete reasoning, such as incorrectly cross-multiplying and solving for \\(k\\) from the wrong ratio. The value 4 is an arithmetic slip from failing to cross-multiply correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JI8H1T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new tutoring program improves exam scores. She emails all 1,230 freshmen inviting them to participate; 174 sign up and are randomly assigned to a tutoring group (87 students) or a control group (87 students). The tutoring group scores an average of 11 points higher on the final exam. Which of the following best describes a limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"Because participants were randomly assigned, the results can be generalized to all 1,230 freshmen."},{"key":"B","text":"The 174 volunteers may differ systematically from the overall freshman class, so the results may not generalize to all freshmen."},{"key":"C","text":"Because the study was observational, no causal conclusion can be drawn about the tutoring program."},{"key":"D","text":"The control group should have received a different tutoring program rather than no tutoring at all."}]$lyceon_json$::jsonb, 'B', NULL, E'Although random assignment within the 174 volunteers supports a causal conclusion (the tutoring likely caused the score increase among such volunteers), the volunteers self-selected into the study. They may be more motivated or academically engaged than the typical freshman, so generalizing the causal effect to all 1,230 freshmen is not justified. The claim that random assignment allows generalization to all freshmen confuses random assignment (which supports causation) with random selection (which supports generalization). Calling this an observational study is incorrect because random assignment was used within the volunteer group. Suggesting the control group should receive a different treatment misunderstands the purpose of a control group in experimental design.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JU30Y9', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'For what value of $a$ does the equation $5(ax - 2) + 3x = 13(x + 1) - 7$ have no solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Expanding both sides: the left side becomes $5ax - 10 + 3x = (5a + 3)x - 10$, and the right side becomes $13x + 13 - 7 = 13x + 6$. Rearranging gives $(5a + 3 - 13)x = 16$, which simplifies to $(5a - 10)x = 16$. For the equation to have no solution, the coefficient of $x$ must be zero while the constant is nonzero. Setting $5a - 10 = 0$ gives $a = 2$. Since $16 \\neq 0$, the equation has no solution when $a = 2$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZ7SFE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours studied ($x$) and exam score ($y$) for several students and finds a line of best fit $y = 4.7x + 53$. What is the best interpretation of the slope 4.7 in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour studied, the predicted exam score increases by 4.7 points."},{"key":"B","text":"For each additional point on the exam, the predicted study time increases by 4.7 hours."},{"key":"C","text":"A student who studies 0 hours is predicted to score 4.7 on the exam."},{"key":"D","text":"The exam score is 4.7 times the number of hours studied."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the change in the predicted y-value for each one-unit increase in x. Here, for each additional hour studied, the predicted exam score increases by 4.7 points. Saying each additional exam point corresponds to 4.7 more hours reverses the roles of the independent and dependent variables. Saying a student who studies 0 hours scores 4.7 confuses the slope with the y-intercept (which is 53). Saying the score is 4.7 times the hours ignores the additive constant and mischaracterizes the relationship as purely multiplicative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2BO7G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Researchers want to estimate the proportion of households in a county that use solar panels. They plan to select a random sample and construct a 95% confidence interval with a margin of error no greater than 4 percentage points. A pilot study suggests that approximately 29% of households use solar panels. They initially plan to survey 350 households. If they want to cut the margin of error in half to 2 percentage points while keeping the confidence level at 95%, what should they do to their sample size?', NULL, $lyceon_json$[{"key":"A","text":"Double the sample size to 700"},{"key":"B","text":"Quadruple the sample size to 1,400"},{"key":"C","text":"Increase the sample size by 50% to 525"},{"key":"D","text":"Keep the sample size at 350 but raise the confidence level"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. To halve the margin of error, the sample size must be multiplied by 4 (since the square root of 4 is 2). Therefore the sample size should increase from 350 to 1,400. Doubling the sample size to 700 would only reduce the margin of error by a factor of the square root of 2 (about 1.41), not by half. Increasing by 50% to 525 applies an incorrect linear relationship. Raising the confidence level while keeping the same sample size would actually increase the margin of error, moving in the wrong direction.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MBSJV9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling organization surveys a random sample of voters in a state and estimates that 43% support a proposed policy, with a margin of error of 3.7 percentage points at a 95% confidence level. Which of the following is the most accurate interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 43% of all voters in the state support the policy."},{"key":"B","text":"Between 39.3% and 46.7% of the sampled voters support the policy."},{"key":"C","text":"It is plausible that the true percentage of all voters in the state who support the policy is between 39.3% and 46.7%."},{"key":"D","text":"If the poll were repeated, exactly 95% of the new samples would yield a result of 43%."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of 3.7 percentage points at 95% confidence means the interval from 43 - 3.7 = 39.3% to 43 + 3.7 = 46.7% is a plausible range for the true population proportion. The statement that exactly 43% of all voters support the policy treats the sample statistic as an exact population parameter, which ignores sampling variability. The claim about sampled voters confuses the population inference with a statement about the sample itself. The assertion that 95% of new samples would yield exactly 43% mischaracterizes the meaning of confidence level.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2METNNO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $18$ centimeters and a height of $11$ centimeters. What is the area, in square centimeters, of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$99$"},{"key":"B","text":"$198$"},{"key":"C","text":"$29$"},{"key":"D","text":"$14.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 18 \\times 11 = 99$ square centimeters. The value $198$ comes from computing $18 \\times 11$ without the $\\frac{1}{2}$ factor, which gives the area of the corresponding rectangle. The value $29$ results from adding $18 + 11$ instead of multiplying, confusing perimeter-style addition with area. The value $14.5$ comes from averaging the two dimensions, $\\frac{18 + 11}{2}$, which is not the area formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OB4Y9N', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the sum of the solutions of $2x^2 - 11x + 15 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/2', ARRAY['11/2', '5.5'], E'By Vieta''s formulas, for $ax^2 + bx + c = 0$, the sum of the roots is $-\\frac{b}{a}$. Here $a = 2$ and $b = -11$, so the sum is $-\\frac{-11}{2} = \\frac{11}{2}$. This can be verified by factoring: $2x^2 - 11x + 15 = (2x - 5)(x - 3) = 0$, giving $x = \\frac{5}{2}$ and $x = 3$, and $\\frac{5}{2} + 3 = \\frac{11}{2}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OF8NKC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'If $f(x) = 7x - 11$, what is the value of $f(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Substituting $x = 3$ into the function: $f(3) = 7(3) - 11 = 21 - 11 = 10$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PEYRYV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, side $\\overline{BC}$ is extended to point $D$. If the measure of angle $BAC$ is $47°$ and the measure of the exterior angle $ACD$ is $119°$, what is the measure, in degrees, of angle $ABC$?', NULL, $lyceon_json$[{"key":"A","text":"$14°$"},{"key":"B","text":"$61°$"},{"key":"C","text":"$72°$"},{"key":"D","text":"$166°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $119° = 47° + \\text{angle } ABC$, which gives angle $ABC = 119° - 47° = 72°$. The value $14°$ results from subtracting $47°$ from $61°$, an intermediate error in setting up the equation. The value $61°$ comes from computing $180° - 119° = 61°$, which is the interior angle at $C$, not the requested angle. The value $166°$ comes from adding $47° + 119°$, misapplying the exterior angle relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYDB3M', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A food truck sells tacos for 4 dollars each and burritos for 7 dollars each. On a particular day, the truck sold 53 items and collected 278 dollars in total revenue. How many burritos were sold that day?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"22"},{"key":"C","text":"31"},{"key":"D","text":"36"}]$lyceon_json$::jsonb, 'B', NULL, E'Let \\(t\\) be the number of tacos and \\(b\\) be the number of burritos. Then \\(t + b = 53\\) and \\(4t + 7b = 278\\). From the first equation, \\(t = 53 - b\\). Substituting into the revenue equation: \\(4(53 - b) + 7b = 278\\), which gives \\(212 - 4b + 7b = 278\\), so \\(3b = 66\\) and \\(b = 22\\). The value 17 results from a subtraction error when simplifying. The value 31 comes from solving for tacos instead of burritos. The value 36 comes from misreading the question and confusing which item costs 4 dollars versus 7 dollars.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RCQ4WR', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $11x - 19 > 47$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding 19 to both sides: $11x > 66$. Dividing by 11: $x > 6$. The only value greater than 6 is 7. The value 4 results from dividing 47 by 11 without first adding 19. The value 5 comes from an arithmetic error in the addition step, computing $47 + 19 = 55$ instead of 66. The value 6 mistakes the boundary for a valid solution, but the inequality is strict ($>$, not $\\geq$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RICE3B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the $xy$-plane, a circle has center $(-5, 7)$ and passes through the point $(3, 1)$. Which of the following is an equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 5)^2 + (y + 7)^2 = 100$"},{"key":"B","text":"$(x + 5)^2 + (y - 7)^2 = 100$"},{"key":"C","text":"$(x + 5)^2 + (y - 7)^2 = 10$"},{"key":"D","text":"$(x - 5)^2 + (y + 7)^2 = 10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. The center is $(-5, 7)$, so the equation includes $(x + 5)^2 + (y - 7)^2$. The radius is the distance from the center to $(3, 1)$: $r = \\sqrt{(3 - (-5))^2 + (1 - 7)^2} = \\sqrt{64 + 36} = \\sqrt{100} = 10$. Thus $r^2 = 100$ and the equation is $(x + 5)^2 + (y - 7)^2 = 100$. The option $(x - 5)^2 + (y + 7)^2 = 100$ uses the wrong signs for the center coordinates. The option $(x + 5)^2 + (y - 7)^2 = 10$ uses $r$ instead of $r^2$ on the right side. The option $(x - 5)^2 + (y + 7)^2 = 10$ combines both the sign error and the failure to square the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S235UA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A car travels 217 miles using 7 gallons of fuel. Fuel costs 3.89 dollars per gallon. At the same rate of fuel consumption, what is the fuel cost, in dollars, for a 589-mile trip?', NULL, $lyceon_json$[{"key":"A","text":"$73.91$"},{"key":"B","text":"$74.83$"},{"key":"C","text":"$69.81$"},{"key":"D","text":"$76.07$"}]$lyceon_json$::jsonb, 'A', NULL, E'The car uses 217 / 7 = 31 miles per gallon. For 589 miles the fuel needed is 589 / 31 = 19 gallons. Total cost is 19 × 3.89 = 73.91 dollars. The value 74.83 results from miscalculating 589 / 31 as approximately 19.236 and then multiplying by 3.89. The value 69.81 comes from dividing 589 by 217 to get approximately 2.71 and multiplying by 7 to get approximately 18.97 gallons, then rounding to 17.95 gallons times 3.89 — a unit-handling error. The value 76.07 results from rounding 589 / 31 up to 19.55 and computing 19.55 × 3.89.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S6UERI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $f(x) = 3x^2 - 12x + 17$ has a minimum value. What is this minimum value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The function is a quadratic with a positive leading coefficient, so it opens upward and has a minimum at its vertex. The x-coordinate of the vertex is $x = -\\frac{b}{2a} = -\\frac{-12}{2(3)} = 2$. Substituting into the function: $f(2) = 3(4) - 12(2) + 17 = 12 - 24 + 17 = 5$. The minimum value of $f$ is $5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SGHQYY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(1, 9)$ and $(4, 21)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 4x + 5$"},{"key":"B","text":"$y = 4x - 5$"},{"key":"C","text":"$y = 3x + 6$"},{"key":"D","text":"$y = 12x - 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{21 - 9}{4 - 1} = \\frac{12}{3} = 4$. Using point-slope form with $(1, 9)$: $y - 9 = 4(x - 1)$, which gives $y = 4x + 5$. The equation $y = 4x - 5$ has the correct slope but a sign error in the intercept calculation. The equation $y = 3x + 6$ uses an incorrect slope from a subtraction error. The equation $y = 12x - 3$ uses the rise value of 12 as the slope without dividing by the run.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SLURAC', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'Solve for $x$: $$7x - 19 = 30$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Adding 19 to both sides gives $7x = 49$. Dividing both sides by 7 yields $x = 7$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SY60S4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of 200 employees asked whether they commute by train or by bus. Of the 200 employees, 74 commute by train, 53 commute by bus, and 19 commute by both train and bus. If an employee who commutes by train is selected at random, what is the probability that this employee also commutes by bus?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{53}$"},{"key":"C","text":"$\\frac{19}{74}$"},{"key":"D","text":"$\\frac{53}{74}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question. Given that the employee commutes by train, the sample space is the 74 train commuters. Of those, 19 also commute by bus. The conditional probability is 19/74. The distractor 19/200 incorrectly uses the total number of employees as the denominator instead of conditioning on train commuters. The distractor 19/53 incorrectly conditions on bus commuters rather than train commuters. The distractor 53/74 uses the total number of bus commuters rather than only those who also take the train.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TUPAOR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A set of 9 test scores has a mean of 74. If a score of 53 is removed from the set, what is the mean of the remaining 8 scores?', NULL, $lyceon_json$[{"key":"A","text":"$76.625$"},{"key":"B","text":"$74$"},{"key":"C","text":"$77.375$"},{"key":"D","text":"$73$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total of all 9 scores is 9 × 74 = 666. Removing the score of 53 gives a total of 666 − 53 = 613 for 8 scores. The new mean is 613 / 8 = 76.625. The value 74 assumes the mean is unchanged after removing a data point, which is only true if the removed value equals the mean. The value 77.375 results from dividing 619 by 8, an arithmetic error in the subtraction step. The value 73 comes from simply subtracting 1 from the original mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UG6HEW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between average daily temperature in degrees Celsius ($t$) and the number of insect sightings ($n$) using $n = 1.9t - 18$. On a day when the temperature was 29 degrees Celsius, the actual number of sightings was 42. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$4.9$"},{"key":"B","text":"$-4.9$"},{"key":"C","text":"$37.1$"},{"key":"D","text":"$-37.1$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is n = 1.9(29) - 18 = 55.1 - 18 = 37.1. The residual equals actual minus predicted: 42 - 37.1 = 4.9. The value -4.9 results from computing predicted minus actual instead of actual minus predicted, reversing the sign. The value 37.1 confuses the predicted value itself with the residual. The value -37.1 both mistakes the predicted value for the residual and applies the wrong sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WI01TF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $43°$ and the measure of angle $Q$ is $68°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$59°$"},{"key":"B","text":"$111°$"},{"key":"C","text":"$137°$"},{"key":"D","text":"$69°$"}]$lyceon_json$::jsonb, 'D', NULL, E'The sum of the interior angles of any triangle is $180°$. Therefore, angle $R = 180° - 43° - 68° = 69°$. The value $59°$ results from a subtraction error when computing $180 - 43 - 68$. The value $111°$ comes from adding $43° + 68°$ instead of subtracting both from $180°$. The value $137°$ comes from subtracting only one angle, $180° - 43° = 137°$, and omitting the second subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0YDT5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A 37-foot ladder leans against a building, forming an angle of $62°$ with the ground. Which of the following expressions gives the height, in feet, that the ladder reaches on the building?', NULL, $lyceon_json$[{"key":"A","text":"$37 \\cos 62°$"},{"key":"B","text":"$37 \\sin 62°$"},{"key":"C","text":"$\\frac{37}{\\sin 62°}$"},{"key":"D","text":"$\\frac{37}{\\cos 62°}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ladder is the hypotenuse (37 ft), and the height on the building is the side opposite the $62°$ angle. Since $\\sin(\\theta) = \\frac{\\text{opposite}}{\\text{hypotenuse}}$, the height equals $37 \\sin 62°$. Using $37 \\cos 62°$ gives the horizontal distance from the base of the building, not the height, by confusing sine and cosine. Dividing $\\frac{37}{\\sin 62°}$ incorrectly inverts the relationship, as does $\\frac{37}{\\cos 62°}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YWGB1B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A rectangular fish tank has a length of $13$ inches, a width of $7$ inches, and a height of $11$ inches. Water fills the tank to a depth of $4$ inches. What is the volume, in cubic inches, of the water in the tank?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '364', ARRAY['364'], E'The water forms a rectangular prism with the same length and width as the tank but a height equal to the water depth. The volume of the water is $13 \\times 7 \\times 4 = 364$ cubic inches. A common error is using the full tank height of $11$ inches instead of the water depth, giving $13 \\times 7 \\times 11 = 1001$. Another error is computing the total tank volume and subtracting incorrectly.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z6C851', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to the line $5x + 2y = 14$ and passes through the point $(5, 3)$. What is the $x$-intercept of this perpendicular line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{5}{2}$"},{"key":"B","text":"$\\frac{5}{2}$"},{"key":"C","text":"$-\\frac{2}{5}$"},{"key":"D","text":"$\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $5x + 2y = 14$ in slope-intercept form gives $y = -\\frac{5}{2}x + 7$, so the slope is $-\\frac{5}{2}$. The perpendicular slope is $\\frac{2}{5}$. Using point-slope form with $(5, 3)$: $y - 3 = \\frac{2}{5}(x - 5)$, which simplifies to $y = \\frac{2}{5}x + 1$. Setting $y = 0$: $0 = \\frac{2}{5}x + 1$, so $x = -\\frac{5}{2}$. The value $\\frac{5}{2}$ drops the negative sign from the final step. The value $-\\frac{2}{5}$ confuses the perpendicular slope with the $x$-intercept. The value $\\frac{7}{2}$ results from an error in computing the $y$-intercept of the perpendicular line.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZF55NA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A company wants to test whether a new ergonomic keyboard reduces wrist pain among office workers. They recruit 86 volunteers: 43 are randomly assigned to use the new keyboard for 8 weeks, and 43 continue using their standard keyboards. At the end of the study, those using the new keyboard report significantly less wrist pain. Which of the following is the best conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new keyboard is likely to reduce wrist pain for all computer users."},{"key":"B","text":"The new keyboard causes a reduction in wrist pain among office workers similar to the volunteers."},{"key":"C","text":"There is an association between keyboard type and wrist pain, but a causal claim cannot be made because this was an observational study."},{"key":"D","text":"The results are invalid because the sample size is too small."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were randomly assigned to treatment and control groups, this is a randomized experiment, which can support a causal conclusion. The causal claim applies to the population similar to the volunteers (office workers), not all computer users. Generalizing to all computer users goes beyond the study population. Calling this an observational study is incorrect because random assignment was used. Dismissing the results solely due to sample size is unwarranted since the study found a significant result with its design.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZIICKI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher finds that cities with more ice cream shops tend to have higher rates of sunburn. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Ice cream shops cause sunburn."},{"key":"B","text":"Sunburn causes people to open ice cream shops."},{"key":"C","text":"There is an association between the number of ice cream shops and sunburn rates, but a causal relationship cannot be established."},{"key":"D","text":"The study proves that ice cream consumption and sunburn are unrelated."}]$lyceon_json$::jsonb, 'C', NULL, E'This is an observational study, so it can establish an association but not causation. A confounding variable, such as warmer climate or sunny weather, likely explains both the number of ice cream shops and the sunburn rate. Claiming ice cream shops cause sunburn incorrectly infers causation from an observational correlation. Claiming sunburn causes ice cream shops reverses the relationship and still incorrectly asserts causation. Saying the variables are unrelated contradicts the observed association.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZRMEAD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 = 169$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Taking the square root of both sides gives $x = \\pm 13$. Since the question asks for the positive solution, $x = 13$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZRX8XE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'How many real solutions does the system of equations have?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20BFJV3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Literary historian Priya Chandrasekaran has challenged the prevailing view that nineteenth-century Tamil novelists simply adapted European narrative conventions wholesale. Examining serialized fiction published in the Madras-based periodical Viveka Chintamani between 1876 and 1893, Chandrasekaran demonstrates that authors such as Vedanayagam Pillai employed recursive narrative frames — stories within stories within stories — that drew on the structural logic of classical Tamil commentarial traditions rather than on the linear plotting characteristic of Victorian realism. However, Chandrasekaran is careful to note that these authors were not working in cultural isolation: they selectively appropriated elements like epistolary chapters and suspense-driven cliffhangers, weaving them into indigenous frameworks in ways that produced a hybrid form irreducible to either tradition alone.', $lyceon_json$[{"key":"A","text":"Nineteenth-century Tamil novelists rejected European literary techniques in favor of traditional Tamil narrative structures."},{"key":"B","text":"Tamil serialized fiction published in Viveka Chintamani between 1876 and 1893 pioneered a distinctly postcolonial style of literary expression."},{"key":"C","text":"Research indicates that early Tamil novelists created a hybrid narrative form by integrating European elements into indigenous structural traditions rather than merely copying Western conventions."},{"key":"D","text":"Recursive narrative frames found in classical Tamil commentarial traditions were more sophisticated than the linear plotting used in Victorian realist novels."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents Chandrasekaran''s argument that Tamil novelists did not simply adopt European conventions but instead blended European elements with indigenous narrative traditions, producing a hybrid form. The correct choice captures both the challenge to the prevailing view and the nuance of hybridity. The option about rejecting European techniques contradicts the passage, which explicitly states that authors appropriated elements like epistolary chapters and cliffhangers. The option about pioneering a postcolonial style introduces a characterization (postcolonial) not supported by the text. The option about Tamil traditions being more sophisticated than Victorian plotting makes a comparative value judgment the passage does not assert.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
