INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22HX1P3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'Ethnomusicologist Kofi Agawu has argued that Western analyses of West African drumming systematically distort the music by imposing a single fixed downbeat onto polyrhythmic patterns that participants experience as having multiple equally valid entry points. According to Agawu, the very notation system used in transcription — staff notation with barlines — embeds an assumption of metric hierarchy that the music itself does not contain.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23AL4MM', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about an archaeological discovery. The student wants to present the discovery and then explain why it challenges a widely held assumption. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24LQ9LV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the municipal arboretum in Decatur, Georgia, hosts a festival celebrating native wildflowers. Last year, a rotating exhibit of time-lapse photographs _______ visitors how quickly certain species of trillium can bloom and fade within a single week.', $lyceon_json$[{"key":"A","text":"showed"},{"key":"B","text":"have shown"},{"key":"C","text":"are showing"},{"key":"D","text":"show"}]$lyceon_json$::jsonb, 'A', NULL, E'The time marker ''Last year'' establishes a completed past action, so the simple past tense ''showed'' is required. The present perfect ''have shown'' (the second option) implies a connection to the present and conflicts with the definite past marker ''Last year.'' The present progressive ''are showing'' (the third option) describes an ongoing action and is inconsistent with the past time frame. The simple present ''show'' (the fourth option) implies a habitual or current action, which contradicts the past-tense context established by ''Last year.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW259OPHS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, marine archaeologist Tomás Quiroga located the wreck of a seventeenth-century galleon off the coast of Belize. Among the artifacts recovered were brass navigational instruments, porcelain fragments, and a sealed copper _______ contained letters written by a colonial governor detailing trade disputes with Dutch merchants.', $lyceon_json$[{"key":"A","text":"canister, which"},{"key":"B","text":"canister. Which"},{"key":"C","text":"canister which"},{"key":"D","text":"canister; which"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause ''which contained letters written by a colonial governor detailing trade disputes with Dutch merchants'' is a nonrestrictive relative clause modifying ''a sealed copper canister.'' A comma before ''which'' correctly sets off this nonrestrictive clause. Starting a new sentence with ''Which'' (the second option) creates a sentence fragment because ''which'' introduces a dependent clause that cannot stand alone. Omitting the comma before ''which'' (the third option) violates the convention that nonrestrictive relative clauses require a preceding comma. Placing a semicolon before ''which'' (the fourth option) is nonstandard because semicolons join independent clauses, and a ''which'' clause is dependent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25K5UCT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Kerguelen Plateau, a submerged volcanic landmass in the southern Indian Ocean, supports an unusually dense concentration of marine organisms. Oceanographers attribute this productivity to deep-water currents that push nutrient-rich sediment upward, and each of the thirteen research stations maintained along the plateau''s eastern _______ water chemistry at regular intervals.', $lyceon_json$[{"key":"A","text":"ridge monitors"},{"key":"B","text":"ridge monitor"},{"key":"C","text":"ridge, monitoring"},{"key":"D","text":"ridge have monitored"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the clause is ''each,'' which is grammatically singular regardless of the prepositional phrase ''of the thirteen research stations'' that follows it. The singular verb ''monitors'' agrees with ''each.'' The plural verb ''monitor'' (the second option) incorrectly treats ''stations'' as the subject. Using a comma and the participial ''monitoring'' (the third option) creates a dangling modifier that lacks a finite verb for the clause. The plural auxiliary ''have monitored'' (the fourth option) also fails to agree with the singular subject ''each.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ASD7GB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Ravina Deshmukh has spent nearly two decades cataloging moth species in the Western Ghats of India. Her team recently identified seventeen previously unknown species in a single monsoon _______ the discovery underscored how much biodiversity remains undocumented in tropical mountain ecosystems.', $lyceon_json$[{"key":"A","text":"season,"},{"key":"B","text":"season;"},{"key":"C","text":"season"},{"key":"D","text":"season; and"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank separates two independent clauses: ''Her team recently identified seventeen previously unknown species in a single monsoon season'' and ''the discovery underscored how much biodiversity remains undocumented in tropical mountain ecosystems.'' A semicolon correctly joins two independent clauses without a conjunction. Using a comma alone creates a comma splice, which is a sentence boundary error. Omitting punctuation entirely creates a run-on sentence. Placing a semicolon before the coordinating conjunction ''and'' is non-standard: a semicolon replaces a conjunction, so using both is redundant and incorrect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BCTJJ7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since the early 1900s. Its genome contains roughly 13,600 genes, about 60 percent of which have recognizable counterparts in humans. Because of this genetic overlap, researchers frequently use Drosophila to model human diseases such as Parkinson''s and Huntington''s. [Underlined: A 2019 study, for example, identified a fly gene whose mutation produces symptoms strikingly similar to early-onset Alzheimer''s.]', $lyceon_json$[{"key":"A","text":"It provides a specific example supporting the preceding claim."},{"key":"B","text":"It introduces a new line of research that challenges an earlier finding."},{"key":"C","text":"It defines a technical term used elsewhere in the passage."},{"key":"D","text":"It summarizes the passage's central argument."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence cites a specific 2019 study about a fly gene linked to Alzheimer''s-like symptoms, directly illustrating the preceding claim that researchers use Drosophila to model human diseases. The choice stating that the sentence introduces a challenge to an earlier finding is incorrect because the study reinforces rather than contradicts the claim about genetic overlap. The choice about defining a technical term is wrong because no term is being defined — a concrete research finding is being presented. The choice about summarizing the central argument is incorrect because the sentence offers one particular instance rather than restating the passage''s overall point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BQHO8I', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 study of soil microbiomes, ecologist Farah Idrissi compared bacterial diversity in agricultural plots that had been treated with synthetic fertilizers to diversity in plots cultivated using traditional composting methods. Idrissi found that the plots _______ with compost for at least seven consecutive growing seasons harbored thirty-one percent more unique bacterial genera than their fertilizer-treated counterparts.', $lyceon_json$[{"key":"A","text":"that had been enriched"},{"key":"B","text":"having been enriched"},{"key":"C","text":"that have been enriched"},{"key":"D","text":"being enriched"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a completed study (''In a 2023 study'') and uses the past tense ''found'' for the main verb. The enrichment of the plots with compost occurred over seven seasons prior to Idrissi''s observation, so the past perfect ''had been enriched'' is needed to indicate an action completed before another past event. The participial phrase ''having been enriched'' (the second option) creates a dangling modifier that lacks a clear grammatical connection to the main clause''s subject. The present perfect ''have been enriched'' (the third option) implies a connection to the present moment, which conflicts with the past-tense framing of the study. The present participle ''being enriched'' (the fourth option) suggests an ongoing action at the time of observation and fails to convey the completed nature of the seven-season treatment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D363C9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleobotanist Mirela Dragoescu has argued that the high density of fossilized cycad pollen in Late Triassic sediments from the Transylvanian Basin indicates a warm, humid paleoclimate in the region. Other researchers have pointed out that cycad pollen can be transported by wind over distances exceeding 800 kilometers, meaning the fossils may have originated far from the depositional site. __________, Dragoescu''s team recently recovered cycad macrofossils — leaves and reproductive structures too heavy for long-distance wind transport — from the same stratigraphic layers, reinforcing the local-growth interpretation.', $lyceon_json$[{"key":"A","text":"Nevertheless"},{"key":"B","text":"In addition"},{"key":"C","text":"Accordingly"},{"key":"D","text":"On the other hand"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a three-part argumentative structure: Dragoescu''s original claim, a counterargument from other researchers about wind transport, and then new evidence that counters the counterargument by showing macrofossils that could not have traveled far. The transition must signal that despite the objection raised in the preceding sentence, the new evidence supports Dragoescu''s position. ''Nevertheless'' correctly introduces information that persists in the face of the preceding objection. ''In addition'' merely adds information without acknowledging the adversative relationship with the counterargument. ''Accordingly'' implies the macrofossil discovery follows logically from the wind-transport objection, which reverses the argumentative direction. ''On the other hand'' introduces a contrasting perspective, but the final sentence does not contrast with the objection — it counters it by returning to support Dragoescu''s original claim, making the concessive ''Nevertheless'' more precise.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EOLRMN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a university research committee. The student wants to argue that a particular methodology is more reliable than an alternative approach by citing specific comparative data. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F6NZEA', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the 1990s, ethnomusicologist Kwabena Osei documented that Akan drum ensembles in southern Ghana used asymmetric rhythmic cycles — patterns of 7 or 11 beats rather than the 4- or 8-beat groupings common in Western music. Osei proposed that these cycles encoded communal work tempos specific to yam-harvesting practices. Subsequent field recordings from Ewe communities in the Volta Region, however, revealed nearly identical asymmetric cycles used in ceremonial contexts unrelated to agriculture. __________, the asymmetric patterns may reflect deeper structural principles of West African musical cognition rather than task-specific functional origins.', $lyceon_json$[{"key":"A","text":"In other words"},{"key":"B","text":"That is to say"},{"key":"C","text":"For example"},{"key":"D","text":"In light of this"}]$lyceon_json$::jsonb, 'D', NULL, E'The final sentence draws a broader conclusion from the evidence presented in the preceding sentence about Ewe communities using the same rhythmic patterns in non-agricultural contexts. The transition must signal that the conclusion is being drawn on the basis of the new evidence. ''In light of this'' correctly indicates that the broader interpretation follows from considering the Ewe evidence. ''In other words'' and ''That is to say'' both signal a restatement or paraphrase of the previous sentence, but the final sentence is not restating the Ewe finding — it is drawing a new, broader inference from it. ''For example'' would introduce a specific illustration of a general claim, but the final sentence moves from specific evidence to a general principle, which is the opposite direction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FZHV06', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientists studying barn owls discovered that the auditory localization circuits in juvenile birds are remarkably plastic. When researchers fitted young owls with prisms that shifted their visual field by 23 degrees, the birds'' auditory maps gradually recalibrated over several weeks to match the displaced visual input — an adjustment that adult owls could not replicate.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"rigid"},{"key":"D","text":"transparent"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes juvenile owls'' auditory circuits gradually recalibrating to match displaced visual input, demonstrating the circuits'' capacity to change and adjust. "Adaptable" captures this meaning of being capable of modification. "Synthetic" refers to something artificially manufactured, which has no connection to neural circuits'' ability to recalibrate. "Rigid" means inflexible and unable to change — the opposite of what the passage describes, since the circuits are shown actively recalibrating. "Transparent" means see-through or easily understood, neither of which relates to the circuits'' demonstrated capacity for reorganization.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1VJDZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Architectural historian Yael Braverman examined how the Ottoman imperial administration adapted Byzantine cistern infrastructure in Istanbul after the 1453 conquest. While earlier scholars assumed the Ottomans simply maintained existing cisterns, Braverman''s analysis of sixteenth-century vakfiye (endowment deeds) reveals that administrators systematically reclassified public cisterns as waqf properties, embedding them within a network of charitable endowments that funded maintenance through rental income from adjacent commercial structures. Braverman argues that this reclassification was not merely administrative but conceptually transformative: by tying cistern upkeep to the religious obligation of charitable endowment, the Ottomans ensured sustained maintenance in a way that the Byzantine civic model — dependent on imperial treasury allocations vulnerable to fiscal crisis — could not. This interpretation implies that the longevity of Istanbul''s cistern infrastructure after 1453 should be attributed less to the physical durability of Byzantine engineering than to ________', $lyceon_json$[{"key":"A","text":"the Ottoman administration's decision to replace Byzantine construction materials with more resilient alternatives during the sixteenth century."},{"key":"B","text":"the institutional framework the Ottomans created, which generated a self-sustaining revenue mechanism for ongoing maintenance."},{"key":"C","text":"the relatively mild seismic activity in the Istanbul region during the first two centuries of Ottoman rule."},{"key":"D","text":"the Ottoman empire's larger treasury reserves compared to those of the late Byzantine state, which allowed for more consistent public spending."}]$lyceon_json$::jsonb, 'B', NULL, E'Braverman''s argument contrasts the Byzantine treasury-dependent model with the Ottoman waqf system, which tied cistern maintenance to rental income from adjacent properties — a self-sustaining mechanism. The logical completion attributes cistern longevity to this institutional framework rather than to physical engineering. The option about replacing construction materials contradicts the passage''s focus on institutional rather than physical changes. The option about mild seismic activity introduces an external factor entirely absent from the text. The option about larger Ottoman treasury reserves misses Braverman''s key point: the advantage was not more treasury spending but a decentralized, self-funding endowment model that removed dependence on treasury allocations altogether.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JJSWZ7', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KKC8OI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economist Fatou Diagne analyzed municipal water pricing in 23 West African cities between 2008 and 2021. She found that cities employing increasing block tariffs — where the per-liter price rises with consumption — achieved 14 percent lower per-capita water use than cities with flat-rate pricing. However, Diagne also observed that in cities with block tariffs, households in the lowest income quintile spent a larger share of their income on water than comparable households in flat-rate cities. This apparent paradox arises because ________', $lyceon_json$[{"key":"A","text":"low-income households in block-tariff cities tend to share metered connections with neighbors, inflating their recorded consumption and pushing them into higher-priced tiers."},{"key":"B","text":"flat-rate pricing structures are generally set at levels too low to cover municipal water treatment and distribution costs."},{"key":"C","text":"wealthier households in block-tariff cities reduced their consumption enough to lower the average, while poorer households lacked the infrastructure to reduce usage comparably."},{"key":"D","text":"West African cities with block tariffs also invested more heavily in water infrastructure, leading to higher overall service quality."}]$lyceon_json$::jsonb, 'C', NULL, E'The paradox is that block tariffs reduce average consumption yet burden low-income households disproportionately. The choice about wealthier households reducing consumption while poorer ones cannot resolves this: the average drops because high-income users cut back, but low-income households remain in higher-priced tiers because they lack alternatives (efficient fixtures, storage, etc.), paying proportionally more. The option about shared metered connections introduces a plausible but unsupported mechanism; the passage provides no information about connection-sharing practices. The option about flat-rate pricing being too low addresses cost recovery, not the paradox about income burden. The option about infrastructure investment describes a possible correlation but does not explain why low-income households specifically bear a heavier cost burden under block tariffs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L2YX2Q', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Groningen recently demonstrated that certain species of Arctic terns adjust their migratory routes in response to shifting wind patterns rather than relying solely on magnetic field orientation. By fitting 47 terns with lightweight GPS trackers over three consecutive breeding seasons, the team found that birds consistently deviated from traditional flyways when encountering sustained crosswinds exceeding 35 kilometers per hour. The finding challenges a decades-old assumption that magnetic cues are the predominant navigational mechanism for long-distance seabirds.', $lyceon_json$[{"key":"A","text":"Arctic terns use wind patterns, not magnetic fields, as their primary navigational tool during migration."},{"key":"B","text":"A study has shown that Arctic terns modify their migratory paths based on wind conditions, questioning the assumed dominance of magnetic navigation."},{"key":"C","text":"GPS tracking technology has advanced sufficiently to allow researchers to monitor the flight paths of small seabirds over multiple years."},{"key":"D","text":"Wind speeds above 35 kilometers per hour pose a significant danger to Arctic terns during their annual migrations."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on a study revealing that Arctic terns adjust migratory routes in response to wind patterns, thereby challenging the assumption that magnetic cues dominate navigation. The correct choice captures both the study''s finding and its implication. The option stating that terns use wind patterns as their primary tool overstates the finding: the study shows terns adjust routes based on wind, not that wind replaces magnetic navigation entirely. The option about GPS technology describes a methodological detail, not the text''s central point. The option about wind speeds posing danger misreads the passage: the text discusses route deviation, not physical risk.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M749XW', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The mountain gorilla population in the Virunga volcanic range had dwindled to fewer than 250 individuals by 1981. Aggressive conservation measures, including round-the-clock ranger patrols and veterinary intervention programs, were introduced shortly afterward. __________, the population has rebounded to over 600 individuals as of recent surveys.', $lyceon_json$[{"key":"A","text":"As a result"},{"key":"B","text":"In contrast"},{"key":"C","text":"For instance"},{"key":"D","text":"Meanwhile"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes conservation measures being introduced and then the gorilla population rebounding, which is a cause-and-effect relationship. The transition ''As a result'' correctly signals that the rebound followed from the conservation efforts. ''In contrast'' incorrectly signals opposition between the two ideas, when in fact the rebound is a consequence of the measures. ''For instance'' incorrectly treats the rebound as an example of the conservation measures rather than an outcome. ''Meanwhile'' incorrectly implies two simultaneous but unrelated events, whereas the passage presents a clear causal sequence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OOGYAS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers studying the venom of the Australian funnel-web spider have identified a peptide that selectively blocks acid-sensing ion channels in human cardiac tissue, offering a potential therapy for damage sustained during heart attacks. __________, the same peptide appears to disrupt signaling pathways essential for normal neural function in laboratory mice, raising concerns about neurological side effects that would need to be addressed before clinical trials could proceed.', $lyceon_json$[{"key":"A","text":"Similarly"},{"key":"B","text":"Consequently"},{"key":"C","text":"However"},{"key":"D","text":"Specifically"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence presents a promising medical application of the spider peptide, while the second sentence introduces a complicating concern about neurological side effects. This is a contrast between a benefit and a drawback, so ''However'' is the correct transition. ''Similarly'' wrongly implies the second finding parallels or reinforces the first, when in fact it complicates it. ''Consequently'' wrongly frames the side-effect concern as a direct result of the cardiac benefit, but the passage presents them as independent findings about the same peptide. ''Specifically'' wrongly suggests the second sentence is elaborating on a detail from the first, when it is actually introducing a conflicting observation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QR8F0Z', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Linguist Haruto Ōmori has spent eleven years documenting whistled speech traditions among communities in the Canary Islands. By the time his comprehensive atlas of silbo registers is published next year, _______ phonetic transcriptions of more than four thousand distinct whistled phrases from nineteen villages.', $lyceon_json$[{"key":"A","text":"he will have compiled"},{"key":"B","text":"he has compiled"},{"key":"C","text":"he compiled"},{"key":"D","text":"he would compile"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction ''By the time ... is published next year'' establishes a future deadline by which an action will be completed. The future perfect tense ''will have compiled'' correctly indicates an action that will be finished before that future point. The present perfect ''has compiled'' (the second option) describes an action completed relative to the present, not relative to a future deadline. The simple past ''compiled'' (the third option) places the action entirely in the past and is incompatible with the future time frame. The conditional ''would compile'' (the fourth option) implies a hypothetical scenario rather than a projected completion before a stated deadline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R1U8VP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the painted bunting''s habitat preferences have shifted in recent decades. Which choice best supports this claim?', E'The painted bunting (Passerina ciris) was historically associated with dense, shrubby thickets at forest edges across the southeastern United States. Wildlife surveys conducted by the Georgia Department of Natural Resources between 2001 and 2019 documented a 29 percent increase in bunting nesting density within suburban hedgerows and ornamental plantings, even as populations in undisturbed forest-edge habitats declined by 17 percent. Researchers attribute this shift partly to the proliferation of seed feeders in residential areas, which may reduce the energetic cost of foraging during the breeding season.', $lyceon_json$[{"key":"A","text":"The painted bunting is historically associated with dense, shrubby thickets at forest edges."},{"key":"B","text":"Surveys found a 29 percent increase in bunting nesting in suburban areas alongside a 17 percent decline in traditional forest-edge habitats."},{"key":"C","text":"Residential seed feeders may reduce the energetic cost of foraging during breeding season."},{"key":"D","text":"The Georgia Department of Natural Resources conducted wildlife surveys from 2001 to 2019."}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that the bunting''s habitat preferences have shifted. The choice citing the 29 percent increase in suburban nesting alongside a 17 percent decline in forest-edge habitats directly demonstrates a measurable shift in where buntings nest. The option about historical association with shrubby thickets describes the bird''s former habitat, not a shift. The option about seed feeders reducing foraging costs offers a possible explanation for the shift but does not itself demonstrate that a shift occurred. The option about the survey''s dates and conducting agency is a methodological detail that provides no evidence of habitat change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RR5KEA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "economy" most nearly mean?', E'Critics have long praised the prose of Marguerite Duras for its startling economy. In her 1984 novella, entire decades of emotional turmoil are compressed into paragraphs of no more than forty words, each clause stripped to its syntactic minimum, yet the cumulative effect is not sparseness but density — every omitted detail seems to press against the surface of the text.', $lyceon_json$[{"key":"A","text":"conciseness"},{"key":"B","text":"thriftiness"},{"key":"C","text":"prosperity"},{"key":"D","text":"management"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes prose in which decades of emotion are compressed into tiny paragraphs with clauses stripped to their syntactic minimum. "Economy" here refers to the efficient, spare use of words — a literary sense meaning conciseness. "Thriftiness" refers to careful spending of money or material resources, not to the deliberate compression of language for artistic effect. "Prosperity" means wealth or financial success, which is entirely unrelated to the passage''s discussion of prose style. "Management" refers to the administration or control of a system or organization, which does not describe the stripped-down quality of Duras''s sentences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SIJVT5', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During a 2021 excavation in northern Peru, archaeologist Lucía Mendivil uncovered a cache of intricately carved gourds dating to roughly 2500 BCE. The gourds, each no larger than a human _______ depict geometric motifs that bear a striking resemblance to patterns found on textiles produced by civilizations that flourished nearly a millennium later.', $lyceon_json$[{"key":"A","text":"fist,"},{"key":"B","text":"fist;"},{"key":"C","text":"fist"},{"key":"D","text":"fist.They"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase ''each no larger than a human fist'' is a parenthetical appositive set off by commas within the sentence ''The gourds ... depict geometric motifs ....'' Because a comma already opens the parenthetical after ''gourds,'' a closing comma after ''fist'' is required to complete the pair and allow the main verb ''depict'' to follow. A semicolon after ''fist'' (the second option) would improperly terminate the parenthetical and create a fragment after it, since ''depict geometric motifs ...'' lacks a subject when severed from ''The gourds.'' Omitting punctuation entirely (the third option) fails to close the parenthetical, creating a confusing run of noun phrases. Fusing ''fist'' directly to ''They'' with a period but no space (the fourth option) is a formatting error that also introduces an unnecessary pronoun shift, since the subject ''The gourds'' is already established.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V1JE7R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2023 paper published in the journal Paleoecology, marine biologist Sana Okafor analyzed fossilized otoliths — tiny ear bones — from eleven fish species preserved in Miocene-era sediment cores drilled off the coast of Namibia. Okafor found that oxygen isotope ratios in these otoliths shifted markedly around 14.7 million years ago, coinciding with a known cooling of the Benguela Current. She argues that the isotopic shift reflects not merely a temperature change but a fundamental reorganization of the regional food web, as cold-tolerant plankton species replaced warm-water varieties, cascading upward through predator-prey relationships.', $lyceon_json$[{"key":"A","text":"Fossilized otoliths provide a uniquely reliable record of ocean temperature changes during the Miocene epoch."},{"key":"B","text":"Analysis of ancient fish ear bones suggests that a current-cooling event triggered broad ecological restructuring rather than a simple temperature shift."},{"key":"C","text":"The Benguela Current underwent a dramatic cooling approximately 14.7 million years ago, which researchers have confirmed through multiple independent methods."},{"key":"D","text":"Sana Okafor's research demonstrates that plankton species are more sensitive to temperature fluctuations than previously believed by marine biologists."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Okafor''s analysis of fossilized otoliths and her argument that isotopic shifts reflect a broad ecological reorganization triggered by the Benguela Current cooling, not merely a temperature change. The correct choice captures both the method and the central claim. The option about otoliths being a reliable temperature record focuses on one aspect of the methodology rather than the broader argument. The option about confirmation through multiple methods introduces information not present in the passage, which discusses only otolith analysis. The option about plankton sensitivity overstates the finding: Okafor discusses plankton replacement as part of a food-web cascade, not a general claim about plankton sensitivity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VFHEK0', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Microbiologist Kenji Toriyama studied colonies of Deinococcus radiodurans, a bacterium renowned for surviving extreme radiation exposure. Toriyama subjected cultures to 5,000 gray of gamma radiation — a dose roughly 1,000 times the lethal threshold for most bacteria — and found that 87 percent of D. radiodurans cells remained viable after 48 hours. Remarkably, these survivors exhibited no increase in mutation rates compared to unirradiated controls, suggesting that the organism''s radiation resistance depends not merely on tolerating DNA damage but on ________', $lyceon_json$[{"key":"A","text":"an unusually efficient mechanism for repairing damaged DNA with high fidelity."},{"key":"B","text":"a metabolic dormancy state that prevents cell division during radiation exposure."},{"key":"C","text":"a thick outer membrane that blocks gamma radiation from reaching the cell's interior."},{"key":"D","text":"a symbiotic relationship with other extremophile microorganisms present in the culture."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that survivors showed no increase in mutation rates despite massive radiation exposure. Since radiation causes DNA damage and mutations arise from improperly repaired damage, the absence of elevated mutation rates implies that the organism repairs DNA damage with exceptional accuracy. The option about metabolic dormancy does not explain the lack of mutations — dormancy might prevent growth but would not repair accumulated damage. The option about a thick membrane blocking radiation is contradicted by the passage''s framing, which discusses surviving radiation rather than avoiding it. The option about symbiosis introduces a concept entirely unsupported by the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XFSLGW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Geochemist Priya Narayanan has argued that volcanic sulfur deposits in the Deccan Traps contributed to mass extinction events more significantly than the asteroid impact alone. Her 2019 analysis of iridium-to-sulfur ratios in boundary _______ challenged the prevailing single-cause hypothesis, prompted several rival labs to re-examine their own core samples from sites in Montana and Denmark.', $lyceon_json$[{"key":"A","text":"clay not only"},{"key":"B","text":"clay, not only"},{"key":"C","text":"clay. Not only"},{"key":"D","text":"clay; not only"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence uses the correlative conjunction pair ''not only ... but also'' (with ''but'' implied before ''prompted'') to link two verb phrases sharing the same subject: ''Her 2019 analysis ... not only challenged ... [but also] prompted ....'' Because ''not only challenged'' and ''prompted'' are compound predicates within a single sentence, no punctuation should appear before ''not only.'' Inserting a comma (the second option) incorrectly separates the subject from its predicate. Starting a new sentence with ''Not only'' (the third option) produces a fragment because ''Not only challenged the prevailing single-cause hypothesis, prompted several rival labs ...'' lacks a subject. A semicolon (the fourth option) similarly breaks the sentence at a point where the second clause has no independent subject, producing a fragment after the semicolon.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XVGZXC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about an architectural innovation. The student wants to emphasize the environmental benefit of the innovation. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
