INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YFF7OE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, marine biologists assumed that deep-sea corals grew too slowly to recover from trawling damage within a human lifetime. Recent expeditions to the Flemish Cap seamounts, however, have documented colonies of Primnoa resedaeformis regenerating damaged branches at rates three to five times faster than laboratory models predicted. The disparity appears linked to nutrient-dense currents that bathymetric ridges funnel across the seamount summits, delivering organic particles at concentrations rarely replicated in controlled settings.', $lyceon_json$[{"key":"A","text":"It presents a longstanding assumption, describes findings that contradict it, and proposes an explanation for the discrepancy."},{"key":"B","text":"It compares two competing theories and argues that neither fully accounts for the observed data."},{"key":"C","text":"It traces the chronological development of a research methodology from its origins to its current form."},{"key":"D","text":"It catalogues several species of deep-sea coral and ranks them by their regeneration rates."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first states an assumption (deep-sea corals recover too slowly), then presents contradictory findings (Primnoa regenerating faster than predicted), and finally offers an explanation (nutrient-dense currents from bathymetric ridges). The choice about comparing two competing theories is incorrect because the passage presents one assumption and one set of contradicting findings, not two rival theories. The choice about tracing chronological development of a methodology is wrong because the passage does not describe how a method evolved over time. The choice about cataloguing several species and ranking them is incorrect because only one species is discussed, and no ranking is provided.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YS0LGF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A historian argues that the 1847 Eli Whitney cotton gin patent extension controversy primarily reflected tensions between Northern manufacturing interests and Southern planter elites, rather than a straightforward dispute over intellectual property law. Which finding, if true, would most directly weaken this argument?', E'When Eli Whitney''s cotton gin patent neared expiration in 1847, a coalition of Southern planters petitioned Congress to deny any extension, arguing that the gin''s design had become so widely replicated that enforcement was impractical. Northern industrialists, who manufactured gin components and profited from licensing fees, lobbied vigorously for renewal. Some historians have framed the episode as a proxy battle in the growing sectional rivalry between North and South. Others contend that the dispute was fundamentally about the evolving legal standards for patent novelty and duration, noting that several contemporaneous patent cases involving Northern inventors and Northern manufacturers produced similarly contentious congressional debates.', $lyceon_json$[{"key":"A","text":"Congressional voting records show that representatives from border states voted in a pattern indistinguishable from their Northern colleagues on the extension question."},{"key":"B","text":"Private correspondence among Southern planters reveals explicit discussions of using the patent dispute to limit Northern economic influence in cotton processing."},{"key":"C","text":"Three other patent extension disputes during the 1840s, all involving Northern patent holders and Northern manufacturers with no sectional dimension, generated comparably intense congressional debate."},{"key":"D","text":"Economic analyses indicate that the cotton gin patent generated significantly more licensing revenue for Northern firms than for Southern ones during the 1840s."}]$lyceon_json$::jsonb, 'C', NULL, E'The historian''s argument is that the controversy was primarily about North-South sectional tensions. To weaken this, one must show the controversy could be explained without sectional dynamics. The finding that three other 1840s patent disputes — all between Northern parties with no sectional element — produced comparably intense debate directly suggests that the intensity of the cotton gin dispute could reflect general patent-law controversies rather than sectional conflict. The finding about border-state voting patterns is only partially relevant: it addresses one region''s behavior but does not demonstrate that the controversy lacked a sectional character overall. The finding about Southern planters explicitly discussing limiting Northern economic influence would strengthen, not weaken, the historian''s argument. The finding about licensing revenue disparities describes an economic fact that could support the sectional-tension reading rather than undermine it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z4HFVP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A botanist hypothesizes that the high concentration of silica in horsetail stems serves primarily as a defense against herbivory rather than as structural support. Which finding, if true, would most directly support this hypothesis?', E'Horsetails (genus Equisetum) are among the most silica-rich vascular plants, accumulating up to 25 percent of their dry weight as biogenic silica deposited in the epidermal cell walls. The abrasive quality of horsetail tissue is well documented — medieval Europeans used the stems to scour metal cookware. While some researchers have proposed that silica deposition stiffens the hollow stems against wind loading, others argue that its primary adaptive value lies in deterring herbivores, since the abrasive particles wear down insect mandibles and mammalian teeth.', $lyceon_json$[{"key":"A","text":"Horsetail species growing in consistently windless greenhouse environments deposit silica at rates comparable to those of wild populations exposed to regular wind."},{"key":"B","text":"Fossilized horsetail stems from the Carboniferous period contained silica concentrations similar to those observed in modern horsetails."},{"key":"C","text":"Horsetails grown in silica-depleted soil produce stems that bend more easily under mechanical stress than stems grown in silica-rich soil."},{"key":"D","text":"The abrasive quality of horsetail tissue has been recognized by humans for practical purposes since at least the medieval period."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis states that silica''s primary function is herbivore defense, not structural support. The finding that horsetails in windless environments still deposit silica at normal rates would undermine the structural-support explanation, thereby lending indirect support to the herbivore-defense hypothesis. The finding about Carboniferous-era silica concentrations addresses evolutionary persistence but does not distinguish between the two proposed functions. The finding about silica-depleted stems bending more easily would actually support the structural-support hypothesis, contradicting the botanist''s claim. The observation about medieval humans using horsetails for scouring is a historical fact already stated in the passage and does not differentially support the herbivore-defense hypothesis over the structural one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZGEUXJ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "deliberate" most nearly mean?', E'The conservator''s approach to restoring the seventeenth-century fresco was deliberate: she spent eleven weeks examining the pigment layers under magnification before applying a single brushstroke, ensuring that no original detail would be compromised by haste.', $lyceon_json$[{"key":"A","text":"intentional"},{"key":"B","text":"leisurely"},{"key":"C","text":"hesitant"},{"key":"D","text":"arbitrary"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the conservator spending eleven weeks examining pigment layers before acting, emphasizing careful, purposeful action rather than haste. "Intentional" captures this sense of purposeful care. "Leisurely" implies relaxed enjoyment rather than careful purpose, which misrepresents the conservator''s disciplined methodology. "Hesitant" suggests fearful uncertainty, but the conservator is described as methodical and assured, not uncertain. "Arbitrary" means random or without reason, which directly contradicts the passage''s emphasis on meticulous, reasoned preparation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
